// Regenerates src/types/acko-icons.d.ts from the installed @acko/icons build.
// The package's own .d.ts imports raw .svg files (typed as string by
// vite/client) while the runtime exports are React SVG components.
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("node_modules/@acko/icons/dist/index.d.ts", "utf8");
const names = [...src.matchAll(/^export \{ (?:\w+ as )?(\w+) \}$/gm)].map((m) => m[1]).sort();

const out = [
  "// GENERATED by scripts/gen-icon-types.mjs — do not edit. Run `npm run gen:icon-types`",
  "// after upgrading @acko/icons. tsconfig `paths` routes \"@acko/icons\" here so",
  "// icons type as React components rather than the string vite/client gives *.svg.",
  'import type { ComponentType, SVGProps } from "react";',
  "",
  "export type AckoIcon = ComponentType<SVGProps<SVGSVGElement>>;",
  "",
  ...names.map((n) => `export declare const ${n}: AckoIcon;`),
  "",
].join("\n");

writeFileSync("src/types/acko-icons.d.ts", out);
console.log(`wrote ${names.length} icon declarations`);
